'use strict';

const emptyTickets = Object.freeze([]);
const initialState = Object.freeze({ nextId: 1, tickets: emptyTickets });

function addTicket(title, details) {
  return { type: 'ticket/add', payload: { title, details } };
}

function toggleTicket(id) {
  return { type: 'ticket/toggle', payload: { id } };
}

function deleteTicket(id) {
  return { type: 'ticket/delete', payload: { id } };
}

function validId(id) {
  if (!Number.isInteger(id) || id < 1) throw new TypeError('invalid id');
}

function ticketReducer(state = initialState, action) {
  if (!action || typeof action !== 'object') return state;

  if (action.type === 'ticket/add') {
    const payload = action.payload || {};
    if (typeof payload.title !== 'string' || payload.title.trim().length === 0 ||
        typeof payload.details !== 'string') {
      throw new TypeError('invalid ticket');
    }
    const ticket = {
      id: state.nextId,
      title: payload.title.trim(),
      details: payload.details,
      status: 'Open'
    };
    return {
      nextId: state.nextId + 1,
      tickets: [...state.tickets, ticket]
    };
  }

  if (action.type === 'ticket/toggle') {
    const id = action.payload && action.payload.id;
    validId(id);
    const index = state.tickets.findIndex((ticket) => ticket.id === id);
    if (index === -1) return state;
    const old = state.tickets[index];
    const changed = {
      id: old.id,
      title: old.title,
      details: old.details,
      status: old.status === 'Open' ? 'Resolved' : 'Open'
    };
    const tickets = state.tickets.slice();
    tickets[index] = changed;
    return { nextId: state.nextId, tickets };
  }

  if (action.type === 'ticket/delete') {
    const id = action.payload && action.payload.id;
    validId(id);
    const index = state.tickets.findIndex((ticket) => ticket.id === id);
    if (index === -1) return state;
    return {
      nextId: state.nextId,
      tickets: state.tickets.filter((ticket) => ticket.id !== id)
    };
  }

  return state;
}

module.exports = {
  initialState,
  addTicket,
  toggleTicket,
  deleteTicket,
  ticketReducer
};
